B=[['希腊 adamas，词干 adamant-','极硬、难以毁坏的材料'],['拉丁 adamas / adamant-；古法语 adamant','硬材料、宝石等名称']]
W=[
E('adamant','/ˈædəmənt/','坚决的；不肯改变主意的','别人怎么劝都推不动，态度像一块坚硬的石头。','英语先有表示极硬材料的名词 adamant，后来有硬的、不可动摇的形容词。传统上把希腊 adamas 联系 a- 不 + daman 征服、驯服，但这一更早分析有争议。',B+[['英语 adamant 名词 → 形容词','极硬材料 → 坚硬的 → 态度坚定的']],'She was adamant that... 是说她坚决认为或坚持某件事。重点是不愿改变立场，不保证她的观点正确，也不一定贬义。有时是守原则，有时是固执，要由事情本身判断。今天最常见的是形容态度，古老的材料名词较少用。','be adamant that + 从句；be adamant about something；remain adamant。','confident 是有信心，adamant 是不肯改口或退让；stubborn 更常带固执的负面评价。',('She was adamant that the work should be checked before publication.','她坚持认为作品发表前必须核查。'),('We offered several alternatives, but he remained adamant about his decision.','我们提出了几种替代方案，但他仍坚决不改变决定。'),sources=['https://www.etymonline.com/word/adamant','https://www.collinsdictionary.com/dictionary/english/adamant']),
E('adamantly','/ˈædəməntli/','坚决地；毫不退让地','把拒绝、反对或否认说得很硬，没有商量余地。','英语 adamant + -ly，把不肯动摇的态度变成动作的方式。',B+[['英语 adamant → adamantly','态度坚定的 → 坚决地表达或行动']],'adamantly deny 常译坚决否认，adamantly opposed 是坚决反对。它强化说话者立场的力度，不提供事实证据：有人 adamantly denied an accusation，只说明否认得很坚决，不能仅凭这个副词判断指控真假。','adamantly refuse；adamantly deny；be adamantly opposed to something。','firmly 也可表示坚定，adamantly 更突出不肯被说服、不愿让步。loudly 是音量大，态度坚决不一定需要大声。',('The editor adamantly refused to publish an unverified claim.','编辑坚决拒绝发表未经核实的说法。'),('Residents were adamantly opposed to closing the only local library.','居民坚决反对关闭当地唯一的图书馆。'),sources=['https://www.etymonline.com/word/adamant','https://www.oxfordlearnersdictionaries.com/us/definition/english/adamantly']),
E('diamond','/ˈdaɪmənd/','钻石；金刚石；菱形；扑克牌方块','同一个名字先落在坚硬宝石上，再借宝石图案指菱形。','与 adamant 同出希腊 adamas；经拉丁语变体、中世纪拉丁 diamant- 和古法语 diamant 形成英语 diamond。不是现代英语 adamant 改几个字母直接造出的。',[['希腊 adamas → 拉丁 adamant-','极硬材料、宝石的旧称'],['中世纪拉丁 diamant- → 古法语 diamant → 英语 diamond','词形变化并收窄为金刚石、钻石'],['英语形状和图案义','菱形；纸牌方块；棒球内场']],'矿物叫金刚石，作为宝石通常叫钻石。diamond 也能表示菱形图案：a diamond on the sign 不一定说标牌镶了一颗宝石。纸牌的 diamonds 就是方块花色；棒球的 diamond 则从四个垒围出的形状得名。古人把这类材料想成不可征服，不表示现实中的钻石绝对不会碎。','a diamond ring 钻戒；a diamond pattern 菱形图案；the ace of diamonds 方块A。','diamond 是具体矿物、宝石或图案；jewel 是更广的宝石或珠宝。形状义也不表示每颗钻石都被切成菱形。',('Tiny diamonds were set around the edge of the ring.','戒指边缘镶着细小的钻石。'),('The fabric has a pattern of blue and white diamonds.','这块布上是蓝白相间的菱形图案。'),('She placed the ace of diamonds on the table.','她把方块A放到了桌上。'),sources=['https://www.etymonline.com/word/diamond','https://www.oxfordlearnersdictionaries.com/definition/english/diamond'])]
ROOT=dict(id='C0302',meaning='征服、驯服〔传统词源解释〕；难以动摇',core='DAM = TAME / SUBDUE',image='像一块极硬的石头，怎么推也不肯改变；从材料的硬，转向态度的硬。',intro='传统词根分析把希腊 adamas 与 a- 不、daman 征服或驯服相连，得到不可征服的画面；但更早来源仍有争议。可靠的共同节点是 adamas 极硬材料：一支走向 adamant 的坚定态度，另一支成为 diamond 的钻石。',forms='adamant 的 -ant 在这里来自希腊词干 adamant-，不是随手加上的现代英语后缀。diamond 经另一条拉丁、法语词形变化进入，不能画成现代 adamant 直接生出 diamond。',branches=[['态度硬，不退让','adamant、adamantly'],['硬材料、宝石与图案','diamond']],contrasts='adamant 是立场坚定，不等于观点正确；diamond 是金刚石或相关图形，也不等于永远无法破坏。词源里的形象不应替代现代事实。',practice='An adamant refusal is difficult to change, just as the old name of diamond suggested an unconquerable material.\n\n坚决的拒绝很难动摇，如同钻石的古老名称让人想到难以征服的材料。',words=[x['word'] for x in W],exclude={w:'专名、虚构材料或冷门专业词，先略过' for w in ['Damian','adamantium','adamantine','adamantinoma']})
